// Typed Scala facade for tau2-bench domain 'retail' — the FIXED, committed
// tool surface the agent calls. Generated by gen_tools.py; regenerate the
// committed facades after a tau2 upgrade with:  ./regen_facades.sh
// (which overwrites these files). Each function dispatches to the in-scope
// tau2 tool via Tau.callTool.

val facadeDomain: String = "retail"

/** Per-domain prompt guidance — see facades/guidance/retail.md. */
val domainGuidance: String =
  """- NEVER ask the customer for an order ID. Call getUserDetails for their `orders`
  list, then getOrderDetails on each and match by the items/description the customer
  gave. Only ask the customer if NO order matches.
- Order IDs are formatted `#W...`. If getOrderDetails returns "Order not found" for an
  id lacking `#`, immediately retry with `#` prepended before telling the customer
  anything is wrong.
- Once the customer says "yes" to a change you already detailed, CALL the action tool
  THIS turn (exchangeDeliveredOrderItems / returnDeliveredOrderItems /
  modifyPendingOrderItems / cancelPendingOrder). Re-asking for confirmation after a
  "yes" is itself a failure.
- After any write, READ the result: if it contains "Error", do NOT say it succeeded —
  fix the args and retry (a new item id must differ from the old; for an exchange change
  ONLY the option the customer named and keep all others identical), or report the real
  outcome.
- Resolve EVERY request in the chat before done(); never end while a follow-up (an added
  return, a reversal) is still open. Use transferToHumanAgents only when policy requires
  it — never because you could not find an order.
- For "cheapest / fewest / best X" requests, enumerate the product's variants and pick
  the true optimum among those with available == true."""

/** Calculate the result of a mathematical expression. */
def calculate(expression: String): String =
  val args = ujson.Obj()
  args("expression") = ujson.Str(expression)
  Tau.callTool("calculate", args)

/** Cancel a pending order. If the order is already processed or delivered, it cannot be cancelled. The agent needs to explain the cancellation detail and ask for explicit user confirmation (yes/no) to proceed. If the user confirms, the order status will be changed to 'cancelled' and the payment will be refunded. The refund will be added to the user's gift card balance immediately if the payment was made using a gift card, otherwise the refund would take 5-7 business days to process. The function returns the order details after the cancellation. */
def cancelPendingOrder(orderId: String, reason: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  args("reason") = ujson.Str(reason)
  Tau.callTool("cancel_pending_order", args)

/** Exchange items in a delivered order to new items of the same product type. For a delivered order, return or exchange can be only done once by the agent. The agent needs to explain the exchange detail and ask for explicit user confirmation (yes/no) to proceed. */
def exchangeDeliveredOrderItems(orderId: String, itemIds: List[String], newItemIds: List[String], paymentMethodId: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  args("item_ids") = ujson.Arr(itemIds.map(ujson.Str(_))*)
  args("new_item_ids") = ujson.Arr(newItemIds.map(ujson.Str(_))*)
  args("payment_method_id") = ujson.Str(paymentMethodId)
  Tau.callTool("exchange_delivered_order_items", args)

/** Find user id by first name, last name, and zip code. If the user is not found, the function will return an error message. By default, find user id by email, and only call this function if the user is not found by email or cannot remember email. */
def findUserIdByNameZip(firstName: String, lastName: String, zip: String): String =
  val args = ujson.Obj()
  args("first_name") = ujson.Str(firstName)
  args("last_name") = ujson.Str(lastName)
  args("zip") = ujson.Str(zip)
  Tau.callTool("find_user_id_by_name_zip", args)

/** Find user id by email. If the user is not found, the function will return an error message. */
def findUserIdByEmail(email: String): String =
  val args = ujson.Obj()
  args("email") = ujson.Str(email)
  Tau.callTool("find_user_id_by_email", args)

/** Get the status and details of an order. */
def getOrderDetails(orderId: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  Tau.callTool("get_order_details", args)

/** Get the inventory details of a product. */
def getProductDetails(productId: String): String =
  val args = ujson.Obj()
  args("product_id") = ujson.Str(productId)
  Tau.callTool("get_product_details", args)

/** Get the inventory details of an item. */
def getItemDetails(itemId: String): String =
  val args = ujson.Obj()
  args("item_id") = ujson.Str(itemId)
  Tau.callTool("get_item_details", args)

/** Get the details of a user, including their orders. */
def getUserDetails(userId: String): String =
  val args = ujson.Obj()
  args("user_id") = ujson.Str(userId)
  Tau.callTool("get_user_details", args)

/** List the name and product id of all product types. Each product type has a variety of different items with unique item ids and options. There are only 50 product types in the store. */
def listAllProductTypes(): String = Tau.callTool("list_all_product_types")

/** Modify the shipping address of a pending order. The agent needs to explain the modification detail and ask for explicit user confirmation (yes/no) to proceed. */
def modifyPendingOrderAddress(orderId: String, address1: String, address2: String, city: String, state: String, country: String, zip: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  args("address1") = ujson.Str(address1)
  args("address2") = ujson.Str(address2)
  args("city") = ujson.Str(city)
  args("state") = ujson.Str(state)
  args("country") = ujson.Str(country)
  args("zip") = ujson.Str(zip)
  Tau.callTool("modify_pending_order_address", args)

/** Modify items in a pending order to new items of the same product type. For a pending order, this function can only be called once. The agent needs to explain the exchange detail and ask for explicit user confirmation (yes/no) to proceed. */
def modifyPendingOrderItems(orderId: String, itemIds: List[String], newItemIds: List[String], paymentMethodId: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  args("item_ids") = ujson.Arr(itemIds.map(ujson.Str(_))*)
  args("new_item_ids") = ujson.Arr(newItemIds.map(ujson.Str(_))*)
  args("payment_method_id") = ujson.Str(paymentMethodId)
  Tau.callTool("modify_pending_order_items", args)

/** Modify the payment method of a pending order. The agent needs to explain the modification detail and ask for explicit user confirmation (yes/no) to proceed. */
def modifyPendingOrderPayment(orderId: String, paymentMethodId: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  args("payment_method_id") = ujson.Str(paymentMethodId)
  Tau.callTool("modify_pending_order_payment", args)

/** Modify the default address of a user. The agent needs to explain the modification detail and ask for explicit user confirmation (yes/no) to proceed. */
def modifyUserAddress(userId: String, address1: String, address2: String, city: String, state: String, country: String, zip: String): String =
  val args = ujson.Obj()
  args("user_id") = ujson.Str(userId)
  args("address1") = ujson.Str(address1)
  args("address2") = ujson.Str(address2)
  args("city") = ujson.Str(city)
  args("state") = ujson.Str(state)
  args("country") = ujson.Str(country)
  args("zip") = ujson.Str(zip)
  Tau.callTool("modify_user_address", args)

/** Return some items of a delivered order. The order status will be changed to 'return requested'. The agent needs to explain the return detail and ask for explicit user confirmation (yes/no) to proceed. The user will receive follow-up email for how and where to return the item. */
def returnDeliveredOrderItems(orderId: String, itemIds: List[String], paymentMethodId: String): String =
  val args = ujson.Obj()
  args("order_id") = ujson.Str(orderId)
  args("item_ids") = ujson.Arr(itemIds.map(ujson.Str(_))*)
  args("payment_method_id") = ujson.Str(paymentMethodId)
  Tau.callTool("return_delivered_order_items", args)

/** Transfer the user to a human agent, with a summary of the user's issue. Only transfer if - the user explicitly asks for a human agent - given the policy and the available tools, you cannot solve the user's issue. */
def transferToHumanAgents(summary: String): String =
  val args = ujson.Obj()
  args("summary") = ujson.Str(summary)
  Tau.callTool("transfer_to_human_agents", args)

/** Call this function when you are done with the task. */
def done(): String = Tau.callTool("done")

